per_call.cmd:
cat > /tmp/summary.py << 'EOF'
import os, re
from datetime import date, timedelta

LOG_DIR = "/app/logs"
TODAY = date(2025, 8, 12)
SEVS = ["ERROR", "WARNING", "INFO"]
pat = re.compile(r'^(\d{4}-\d{2}-\d{2})')

counts = {p: {s: 0 for s in SEVS} for p in ["today","last_7_days","last_30_days","month_to_date","total"]}

for fn in os.listdir(LOG_DIR):
    m = re.match(r'^(\d{4})-(\d{2})-(\d{2})_.*\.log$', fn)
    if not m:
        continue
    d = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    periods = []
    if d == TODAY:
        periods.append("today")
    if (TODAY - d).days < 7:
        periods.append("last_7_days")
    if (TODAY - d).days < 30:
        periods.append("last_30_days")
    if d.year == TODAY.year and d.month == TODAY.month and d <= TODAY:
        periods.append("month_to_date")
    periods.append("total")
    with open(os.path.join(LOG_DIR, fn)) as f:
        for line in f:
            for sev in SEVS:
                if f"[{sev}]" in line:
                    for p in periods:
                        counts[p][sev] += 1

with open("/app/summary.csv","w") as out:
    out.write("period,severity,count\n")
    for p in ["today","last_7_days","last_30_days","month_to_date","total"]:
        for sev in SEVS:
            out.write(f"{p},{sev},{counts[p][sev]}\n")
print(open("/app/summary.csv").read())
EOF
python3 /tmp/summary.py
